            const skipped=Number(result.skipped_conflicts||0);
            const skippedProtected=Number(result.skipped_protected||0);
            state.ui.partnerAgendaMonth=data.startDate.slice(0,7);
            state.ui.partnerAgendaDate=data.startDate;
            saveState();render();
